[8384] = { en = "Claiming Arathi Basin", tier = 2,
  t = "Arathi Basin opeisen",
  d = "Een oorlog winnen gaat om meer dan alleen slimmer zijn en beter vechten dan je tegenstander. De overwinning komt vaak gewoon neer op meer produceren dan je vijand.$B$BIn Arathi Basin ligt een flinke voorraad grondstoffen, voor de kant die het als eerste weet op te eisen.$B$BAls de Alliance wint, betekent dat meer zwaarden en pieken voor onze troepen. Als de Horde zou winnen, worden die zwaarden en pieken nog steeds gemaakt... maar dan zijn ze op ons gericht! Nu is het moment om de Alliance te helpen in Arathi Basin, $N.",
  o = "Breng 3 Arathi Basin Marks of Honor naar een Alliance Brigadier General buiten de slagvelden.",
  p = "Vertel eens, wat is het nieuws van het front?",
  c = "Goed werk, soldaat! Ga zo door, en we jagen de Horde helemaal terug naar Orgrimmar.",
  g = { {"opeisen", "to claim"}, {"tegenstander", "opponent"}, {"overwinning", "victory"}, {"voorraad", "supply"}, {"grondstoffen", "resources (grondstof)"}, {"zwaarden", "swords (zwaard)"}, {"pieken", "pikes (piek)"}, {"troepen", "troops (troep)"}, {"gericht", "pointed (richten)"}, {"slagvelden", "battlegrounds (slagveld)"}, {"front", "front"} },
},

[536] = { en = "Down the Coast", tier = 2,
  t = "Langs de kust",
  d = "Overgeplaatst van de stadswacht van Stormwind naar Southshore. Zo te zien kun je deze stad beter verlaten... Dag en nacht de geur van de haven.$b$bEn dan heb ik het nog niet eens over de oude Redpath... Hij wil dat ik de murlocs aanpak. Ha!$b$bIk kan mezelf amper zover krijgen om naar een paar van die groepjes uit de kluiten gewassen vissen langs de Western Strand te gaan. Als jij in mijn plaats gaat en ze aanpakt, zou ik dat waarderen.",
  o = "Dood 10 Torn Fin Tidehunters en 10 Torn Fin Oracles voor Lieutenant Farren Orinelle in Southshore.",
  p = "Nog een bier, alsjeblieft, het vorige lijkt gewoon verdwenen te zijn!$B$BLicht, hoe lang zit ik hier nog vast?$B$BO, jij bent het, $N. Heb je die murlocs al gedood?",
  c = "Ik hoop dat dit genoeg is om Redpath ervan te overtuigen dat ik... ha!... zijn bevelen heb uitgevoerd. Dat ik Southshore heb bevrijd van het vreselijke en verschrikkelijke gevaar van de gevreesde murlocs! Want er bestaat geen groter kwaad dan de verwoesting door uit de kluiten gewassen vissen!",
  g = { {"overgeplaatst", "transferred (overplaatsen)"}, {"stadswacht", "city guard"}, {"zo te zien", "by the looks of it"}, {"haven", "harbor"}, {"aanpak", "deal with (aanpakken)"}, {"amper", "barely"}, {"zover krijgen", "to get oneself to (do)"}, {"uit de kluiten gewassen", "overgrown, oversized"}, {"waarderen", "to appreciate"}, {"vast", "stuck"}, {"overtuigen", "to convince"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"bevrijd", "rid, freed (bevrijden)"}, {"gevreesde", "dreaded (gevreesd)"}, {"verwoesting", "ravages, destruction"} },
},

[555] = { en = "Soothing Turtle Bisque", tier = 2,
  t = "Kalmerende schildpadsoep",
  d = "Als je één ding leert over Southshore, dan is het dat we hier een van de beste keukens ten noorden van Stormwind hebben!$b$bNeem nou mijn geheime recept voor schildpadsoep. Ik ken mensen die helemaal uit Darkshire kwamen, alleen om een kom te eten. Daarover gesproken: ik heb de laatste tijd geen soep kunnen maken. Vroeger ging ik zelf voorbij Dalaran naar Lake Lordamere, om op Snapjaws te jagen. Maar dat is nu gewoon te gevaarlijk. Als je me wat Turtle Meat brengt van de Snapjaws in het noorden, en Soothing Spices, dan maak ik snel wat!",
  o = "Breng 10 stukken Turtle Meat en wat Soothing Spices naar Chef Jessen in Southshore.",
  p = "Heb je de ingrediënten al gevonden? Ik zeg je, dit gebied is niet meer zo vredig als vroeger. Ach, was die onrust maar nooit gebeurd...",
  c = "Iedereen zal zo blij zijn: de Soothing Turtle Bisque van Chef Jessen wordt weer geserveerd!",
  g = { {"kalmerende", "soothing (kalmerend)"}, {"keukens", "cuisines (keuken)"}, {"geheime", "secret (geheim)"}, {"kom", "bowl"}, {"daarover gesproken", "speaking of which"}, {"vroeger", "used to, in the past"}, {"jagen", "to hunt"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"gebied", "territory, area"}, {"vredig", "peaceful"}, {"onrust", "unrest"}, {"geserveerd", "served (serveren)"} },
},

[681] = { en = "Northfold Manor", tier = 2,
  t = "Northfold Manor",
  d = "We voeren een oorlog om Stromgarde, en we zijn aan het verliezen. De ogers, het Syndicate en wij hebben onze ooit zo grote stad verdeeld. Elke groep vecht tegen de andere, en zo is er een bloedige patstelling ontstaan.$B$BMaar onze troepen worden kleiner, terwijl onze vijand groeit.$B$BWe hebben hulp nodig uit de stad Southshore. Maar het is moeilijk om voorraden te krijgen, zolang het Syndicate het gebied tussen ons in handen heeft.$B$BGa naar de basis van het Syndicate in Northfold Manor en dood ze. Misschien wordt de druk op onze voorraadkaravanen dan minder, en komt er meer door.",
  o = "Dood 10 Syndicate Highwaymen en 6 Syndicate Mercenaries.$B$BGa terug naar Captain Nials in Refuge Pointe.",
  p = "$N, met elk uur dat voorbijgaat, wordt onze greep op Stromgarde zwakker. Je moet opschieten, anders valt onze stad zeker.",
  c = "Heel goed, $N. Nu die leden van het Syndicate dood zijn, kunnen we makkelijker voorraden uit Southshore krijgen.$b$bMisschien is er toch nog hoop voor onze zaak.",
  g = { {"voeren", "to wage"}, {"verdeeld", "divided (verdelen)"}, {"bloedige", "bloody (bloedig)"}, {"patstelling", "stalemate"}, {"ontstaan", "arisen (ontstaan)"}, {"voorraden", "supplies (voorraad)"}, {"in handen heeft", "holds (in handen hebben)"}, {"druk", "pressure"}, {"voorraadkaravanen", "supply trains (voorraadkaravaan)"}, {"greep", "hold, grip"}, {"opschieten", "to hurry"}, {"zaak", "cause"} },
},

[559] = { en = "Farren's Proof", tier = 2,
  t = "Het bewijs van Farren",
  d = "Kun je het geloven, $n? Redpath was niet tevreden met alle murlocs die we hebben gedood. O, kom nou, wees niet zo bescheiden, jij had er ook een hand in. Nu wil hij dat ik bewijs breng van de doden. Ik moet koude, slijmerige murlockoppen afhakken, zodat hij ze kan goedkeuren.",
  o = "Verzamel 10 Murloc Heads van de murlocs op de Western Strand voor Lieutenant Farren Orinelle in Southshore.",
  p = "Heb je die koppen voor me, $N?",
  c = "O, bij het Licht... ze druipen op de grond.$b$bIk kan zelf niet tegen het aanraken van die dingen. Vis is prima, maar als ze benen krijgen en gaan rondlopen... Ik heb al weken geen vis gegeten, dat zeg ik je. En in Southshore betekent dat dat je niet veel eet.",
  g = { {"bewijs", "proof"}, {"tevreden", "satisfied"}, {"bescheiden", "modest"}, {"een hand in hebben", "to have a hand in"}, {"slijmerige", "slimy (slijmerig)"}, {"koppen", "heads (kop)"}, {"afhakken", "to hack off"}, {"goedkeuren", "to approve"}, {"druipen", "drip (druipen)"}, {"kan niet tegen", "can't stand (niet tegen iets kunnen)"}, {"aanraken", "touching"}, {"rondlopen", "to walk around"} },
},

[560] = { en = "Farren's Proof", tier = 2,
  t = "Het bewijs van Farren",
  d = "Weet je, $n, ik neem die koppen echt liever niet aan... Jij hebt ze nu toch al vast. Wil je ze voor mij naar Redpath brengen?",
  o = "Breng de zak met murlockoppen naar Marshal Redpath in Southshore.",
  p = "Gegroet, burger. Kom je je arm lenen om de veiligheid van Southshore te bewaren?",
  c = "Jij bent de loopjongen van Farren, hè?$b$bAls je Farren hebt geholpen om deze koppen te verzamelen, dan dank je wel. Southshore heeft harde werkers en inzet nodig om beschermd te blijven.",
  g = { {"liever niet", "rather not"}, {"vast", "hold (vasthebben)"}, {"zak", "sack"}, {"gegroet", "greetings"}, {"burger", "citizen"}, {"lenen", "to lend"}, {"veiligheid", "safety"}, {"bewaren", "to uphold, keep"}, {"loopjongen", "errand boy"}, {"inzet", "effort"}, {"beschermd", "protected (beschermen)"} },
},

[561] = { en = "Farren's Proof", tier = 2,
  t = "Het bewijs van Farren",
  d = "Vertel Lieutenant Orinelle alsjeblieft dat ik wil dat hij zich nu richt op de naga die de Eastern Strand teisteren. Als hij resultaten heeft, moet hij persoonlijk bij mij verslag komen doen.",
  o = "Praat met Lieutenant Farren Orinelle in Southshore.",
  c = "De naga, hè? Redpath heeft vast net hetzelfde nieuws gekregen als ik... Ha! Hij krijgt geen promotie dankzij mijn harde werk. Laat me het uitleggen.",
  g = { {"zich richt op", "refocuses on (zich richten op)"}, {"teisteren", "infest, plague"}, {"resultaten", "results (resultaat)"}, {"persoonlijk", "in person"}, {"verslag doen", "to report"}, {"promotie", "promotion"}, {"dankzij", "thanks to"}, {"uitleggen", "to explain"} },
},

[562] = { en = "Stormwind Ho!", tier = 2,
  t = "Op naar Stormwind!",
  d = "Mijn vroegere mentor bij de stadswacht van Stormwind stuurde me een bericht. Alliance High Command maakt zich zorgen over de dreiging van de naga. Hij heeft gehoord dat iedereen die hierbij waardevol blijkt, een goede kans maakt op promotie, of in elk geval op overplaatsing.$b$bEr is alleen één klein probleem... Ik kan de naga niet aan, $n. O, natuurlijk kan ik een vechtpartij tussen dronken mensen in een kroeg stoppen, of een agressieve bedelaar wegslepen. Maar de naga zijn te veel voor mij. Je moet me helpen, $n!",
  o = "Dood 10 Daggerspine Shorehunters en 10 Daggerspine Sirens voor Lieutenant Farren Orinelle in Southshore.",
  p = "Ik heb een brief klaar voor Major Samuelson in Stormwind. Ik heb alleen de resultaten nog nodig.",
  c = "Nu de naga in Southshore verslagen zijn, word ik zeker overgeplaatst. Dan zie ik Stormwind weer... weg uit deze haven die door het Licht vergeten is.",
  g = { {"vroegere", "former (vroeger)"}, {"mentor", "mentor"}, {"dreiging", "threat"}, {"waardevol", "valuable"}, {"blijkt", "proves to be (blijken)"}, {"overplaatsing", "reassignment, transfer"}, {"vechtpartij", "brawl"}, {"dronken", "drunk"}, {"kroeg", "bar, pub"}, {"agressieve", "belligerent, aggressive (agressief)"}, {"bedelaar", "beggar"}, {"wegslepen", "to haul off"}, {"vergeten", "forgotten, forsaken"} },
},

[563] = { en = "Reassignment", tier = 2,
  t = "Overplaatsing",
  d = "Het moet geen probleem zijn om mijn verslag gelezen te krijgen. De nieuwe kapitein van de wacht, Major Samuelson, was mijn mentor toen ik in Stormwind gestationeerd was. Dit geeft hem meer dan genoeg reden om me terug te laten overplaatsen naar de stad. Maar jij moet mijn verslag wel naar hem brengen... de oude Redpath mag er niets van merken.",
  o = "Breng het verslag van Farren naar Major Samuelson in Stormwind Keep.",
  p = "Gegroet, burger. Kan de stadswacht van Stormwind je helpen?",
  c = "Wat is dit? Ah... dus mijn oplettende leerling heeft zich ingezet voor het probleem van de naga in Southshore. Dank je dat je dit bij me brengt. Ik zal er zeker rekening mee houden als ik volgende maand de taken van het personeel bekijk.",
  g = { {"verslag", "report"}, {"gestationeerd", "stationed"}, {"reden", "reason, excuse"}, {"merken", "to notice, catch on"}, {"oplettende", "attentive (oplettend)"}, {"leerling", "pupil"}, {"zich ingezet", "applied himself (zich inzetten)"}, {"rekening mee houden", "take into account"}, {"personeel", "personnel"}, {"taken", "assignments, tasks (taak)"} },
},

[659] = { en = "Hints of a New Plague?", tier = 2,
  t = "Tekenen van een nieuwe pest?",
  d = "Gegroet, en welkom, $N. Ik leid een groep avonturiers die vreemde gebeurtenissen in deze streek onderzoekt.$B$BMijn neef in Hillsbrad heeft kort geleden zijn hond Stanley gedood. Het dier was op een mysterieuze manier enorm groot geworden, en viel iedereen die in de buurt kwam woest aan.$B$BIk denk dat de ondoden ermee te maken hebben. We zoeken naar tekenen om dat te bewijzen.$B$BTwee van mijn metgezellen, Quae en Kinelory, gingen naar de Go'Shek Farm in de Arathi Highlands. Ik heb al dagen niets van ze gehoord. Wil je ze voor me zoeken? Ik begin me zorgen te maken.",
  o = "Zoek Quae en Kinelory bij de Go'Shek Farm in de Arathi Highlands.",
  c = "Probeer zo stil mogelijk te zijn, reiziger.$B$BOrks vinden het niet leuk als ze bespioneerd worden. En er is meer aan de hand op deze boerderij dan je ziet.",
  g = { {"tekenen", "signs, hints (teken)"}, {"pest", "plague"}, {"avonturiers", "adventurers (avonturier)"}, {"gebeurtenissen", "happenings (gebeurtenis)"}, {"streek", "area, region"}, {"onderzoekt", "investigates (onderzoeken)"}, {"neef", "cousin"}, {"mysterieuze", "mysterious (mysterieus)"}, {"enorm", "immensely"}, {"woest", "savagely"}, {"ermee te maken hebben", "to be involved"}, {"metgezellen", "companions (metgezel)"}, {"bespioneerd", "spied on (bespioneren)"}, {"meer aan de hand", "more going on"} },
},

[564] = { en = "Costly Menace", tier = 2,
  t = "Een dure bedreiging",
  d = "Er is niks dat me meer ergert dan het verliezen van deze prachtige paarden. En geloof me, we zijn er heel wat kwijtgeraakt. Door die vervelende ondode griezels, die verdraaide bende van het Syndicate, en al die andere nietsnutten en schurken die hier rondhangen.$b$bMaar ik zweer op het graf van mijn ouwe opa: er is geen grotere bedreiging voor onze paarden dan die Mountain Lions daarboven in Alterac. Ze komen altijd uit de heuvels naar beneden en maken mijn leven moeilijk!$b$bVind je jezelf een held? Ga er dan wat aan doen!",
  o = "Darren Malvew uit Southshore wil dat je 8 Mountain Lions en 10 Hulking Mountain Lions doodt.",
  p = "Mountain Lions doden links en rechts onze paarden, en jij staat hier te kletsen over het weer en zo.$B$BIk zou eens een echte held moeten zoeken. Meer doden en minder praten.",
  c = "Dat is nog eens goed nieuws! Ik had meteen vanaf de eerste dag een echte ouwe oorlogsheld moeten zoeken om die beesten aan te pakken. Je vader zou trots op je zijn geweest, $N.",
  g = { {"bedreiging", "menace, threat"}, {"ergert", "irks, annoys (ergeren)"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"vervelende", "pesky (vervelend)"}, {"griezels", "creeps (griezel)"}, {"verdraaide", "dang, darned (verdraaid)"}, {"bende", "gang"}, {"schurken", "scoundrels (schurk)"}, {"zweer", "swear (zweren)"}, {"graf", "grave"}, {"opa", "granddad"}, {"kletsen", "to chat, jibber-jabber"}, {"links en rechts", "left and right"}, {"oorlogsheld", "war hero"} },
},

[565] = { en = "Bartolo's Yeti Fur Cloak", tier = 2,
  t = "De Yeti Fur Cloak van Bartolo",
  d = "Ik, de grote Bartolo, zal voor jou de wereldberoemde, in de hele Alliance bekende Yeti Fur Cloak maken!$b$bReis de hele wereld rond en zoek een betere mantel. Ik daag je uit. O, wacht, wat zeg je, kleine $r? \"Bartolo, er is geen mooiere mantel!\" Ja, ja! Dat heb ik al eens eerder gehoord.$b$bBartolo heeft nodig: een Bolt of Wool, een Hillman's Cloak die gemaakt is door een goede leerbewerker, Fine Thread en natuurlijk Yeti Fur! Breng mij deze spullen, en je wordt een blije klant!",
  o = "Breng Bartolo Ginsetti uit Southshore een Bolt of Wool, een Hillman's Cloak, Fine Thread en 10 plukken Yeti Fur.",
  p = "Zo, je bent teruggekomen bij de grote Bartolo. Heb je misschien alle materialen verzameld voor je Yeti Fur Cloak? Of geniet je gewoon van de grootsheid van mij, Bartolo!",
  c = "Nu is het tijd voor de grote Bartolo om zijn magie te laten werken! Ik heb geen tovenaarsstaf nodig, geen toverstok van een $C. Want ik, de grote Bartolo, doe magie met alleen een naald en draad!",
  g = { {"wereldberoemde", "world famous (wereldberoemd)"}, {"mantel", "cloak"}, {"daag uit", "dare, challenge (uitdagen)"}, {"leerbewerker", "leatherworker"}, {"klant", "customer"}, {"plukken", "clumps (pluk)"}, {"materialen", "materials (materiaal)"}, {"grootsheid", "greatness"}, {"tovenaarsstaf", "wizard's staff"}, {"toverstok", "wand, rod"}, {"naald", "needle"}, {"draad", "thread"} },
},

[635] = { en = "Crystal in the Mountains", tier = 2,
  t = "Kristal in de bergen",
  d = "Deze scherf pulseert als je hem vasthoudt...$B$BJe voelt een smeekbede uit de scherf komen. Het is alsof iemand iets probeert te zeggen, iemand die heel hard je hulp nodig heeft.$B$BEr verschijnt een visioen in je hoofd: de noordelijke bergen van Arathi, en een stralend kristal dat daar uit de aarde steekt.$B$BJe voelt dat die plek je aantrekt.",
  o = "Zoek het kristal uit je visioen.",
  c = "Dit kristal pulseert, alsof er een levende kracht in gevangen zit.",
  g = { {"scherf", "shard"}, {"pulseert", "pulses (pulseren)"}, {"smeekbede", "plea"}, {"visioen", "vision"}, {"verschijnt", "appears (verschijnen)"}, {"noordelijke", "northern (noordelijk)"}, {"stralend", "brilliant, shining"}, {"steekt", "juts (steken)"}, {"aantrekt", "draws, attracts (aantrekken)"}, {"gevangen", "trapped"} },
},

[636] = { en = "Legends of the Earth <NYI>", tier = 2,
  t = "Legendes van de aarde <NYI>",
  d = "Dit boek vertelt het verhaal van Myzrael, een prinses van de elementen. Het vertelt ook hoe ze diep onder de Arathi Highlands gevangen is gezet.$B$BHet boek vertelt ook over een geheime plek met kristallen in de hooglanden. Deze kristallen, de Shards of Myzrael, zijn een venster naar de gevangenis van de prinses.$B$BAls een dappere ziel de Shards of Myzrael vond, dan kon $ghij:zij; misschien met haar praten...",
  o = "Zoek de Shards of Myzrael.",
  g = { {"legendes", "legends (legende)"}, {"elementen", "elements (element)"}, {"gevangen gezet", "imprisoned (gevangenzetten)"}, {"geheime", "secret (geheim)"}, {"kristallen", "crystals (kristal)"}, {"hooglanden", "highlands (hoogland)"}, {"venster", "window"}, {"gevangenis", "prison"}, {"dappere", "brave (dapper)"}, {"ziel", "soul"} },
},

[663] = { en = "Land Ho!", tier = 2,
  t = "Land in zicht!",
  d = "Lolo ziet een piepkleine $r! Altijd op de uitkijk, dat is Lolo!$b$bWelkom in Faldir's Cove. Captain O'Breen zei dat we hier maar een paar uur zouden blijven. Net lang genoeg om de schat te verzamelen en terug te gaan naar Booty Bay.$b$bMaar Lolo denkt dat we hier veel langer blijven. We zijn de andere twee schepen uit onze vloot kwijtgeraakt. Arme Spirit of Silverpine en Maiden's Folly. Op de bodem van de zee rusten ze nu!$b$bLolo raadt je aan om met Captain O'Breen te praten, als je van plan bent om hier te blijven.",
  o = "Praat met Captain O'Breen in Faldir's Cove.",
  c = "Ahoi, maat.$b$bHet was een vreselijke puinhoop. Seahorn pakt mijn schip af als hij hoort wat er gebeurd is.$b$bEen van de apparaten van de Professor gaf aan dat de verloren schat bij deze baai lag. Ik bracht de Harbinger naar de kade, en ik gaf de Spirit of Silverpine en de Maiden's Folly een teken om hetzelfde te doen.$b$bToen rommelde de zee. Het water zakte, en de twee schepen liepen te pletter op het rif.$b$bHet is niet zomaar een rif. Er zit daar beneden iets...$b$bHelp mijn bemanning, en je wordt rijk beloond.",
  g = { {"land in zicht", "land ho"}, {"piepkleine", "tiny (piepklein)"}, {"op de uitkijk", "on the lookout"}, {"schat", "treasure"}, {"vloot", "fleet, formation"}, {"bodem", "bottom"}, {"raadt aan", "suggests, advises (aanraden)"}, {"puinhoop", "mess"}, {"apparaten", "contraptions, devices (apparaat)"}, {"kade", "dock"}, {"rommelde", "rumbled (rommelen)"}, {"te pletter lopen", "to crash, be wrecked"}, {"rif", "reef"}, {"bemanning", "crew"} },
},

[657] = { en = "Hints of a New Plague?", tier = 3,
  t = "Tekenen van een nieuwe pest?",
  d = "<Quae begint de map door te bladeren.>$B$BDit IS interessant. Het lijkt erop dat Apothecary Jorell hier op Go'Shek aan dodelijke experimenten werkt. Ik weet niet wat dat met Hillsbrad te maken heeft, maar Phin zou het niet fijn vinden als we het laten doorgaan.$B$BTerwijl jij weg was, kregen we het aan de stok met een paar orks. Ik ben niet in goede genoeg conditie om Kinelory te helpen. Als je er zin in hebt: zij heeft bescherming nodig als ze naar de boerderij gaat om het onderzoek te stelen dat Jorell nog niet naar Tarren Mill heeft gestuurd.",
  o = "Praat met Kinelory.",
  c = "Als Phin daardoor rust krijgt, vernietig ik persoonlijk elke Forsaken die er is. Hij heeft sinds de pest zoveel voor ons gedaan. We hadden nooit gedacht dat we nog eens vrienden of familie zouden vinden.$B$BLaat het me weten als je er klaar voor bent. Dan beginnen we meteen.",
  g = { {"map", "folder"}, {"door te bladeren", "to leaf through (doorbladeren)"}, {"dodelijke", "deadly (dodelijk)"}, {"experimenten", "experiments (experiment)"}, {"doorgaan", "to continue"}, {"het aan de stok krijgen met", "to have a run-in with"}, {"conditie", "shape, condition"}, {"zin in hebben", "to be up for"}, {"bescherming", "protection"}, {"onderzoek", "research"}, {"rust", "peace, rest"}, {"vernietig", "destroy (vernietigen)"}, {"persoonlijk", "personally"} },
},

[658] = { en = "Hints of a New Plague?", tier = 3,
  t = "Tekenen van een nieuwe pest?",
  d = "Dus Phin heeft je gestuurd om te kijken hoe het met ons gaat? Dat verbaast me niet. Hij maakt zich te veel zorgen.$B$BWe houden de boerderij al dagen in de gaten. Kin zegt dat ze niet lang geleden een koerier uit dat kleine huis in het zuiden zag komen.$B$BZe praat veel, maar ik kan altijd op haar zintuigen vertrouwen als we in gevaarlijke gebieden zijn.$B$BJij bent zeker geen goede spoorzoeker? We denken dat de koerier misschien aantekeningen naar Tarren Mill brengt. Als we die documenten in handen kunnen krijgen, werpen ze misschien wat licht op wat er in Hillsbrad gebeurt.",
  o = "Zoek de Forsaken Courier en breng haar Sealed Folder terug naar Quae bij de Go'Shek Farm.",
  p = "We waarderen het dat je helpt zoeken naar die koerier, $N.$B$BTerwijl jij weg was, zag Kin een apotheker uit datzelfde huis in het zuiden komen. Ik weet zeker dat ze iets slechts van plan zijn. Ik heb alleen bewijs nodig voordat we iets overhaasts doen.$B$BHeb je al geluk gehad?",
  c = "Uitstekend!$B$BEens kijken waar dit over gaat...",
  g = { {"verbaast", "surprises (verbazen)"}, {"in de gaten houden", "to keep an eye on"}, {"koerier", "courier"}, {"zintuigen", "senses (zintuig)"}, {"vertrouwen", "to trust"}, {"spoorzoeker", "tracker"}, {"aantekeningen", "notes (aantekening)"}, {"in handen krijgen", "to get hold of"}, {"licht werpen op", "to shed light on"}, {"waarderen", "to appreciate"}, {"apotheker", "apothecary"}, {"overhaasts", "rash"}, {"eens kijken", "let's see"} },
},

[691] = { en = "Worth Its Weight in Gold", tier = 3,
  t = "Zijn gewicht in goud waard",
  d = "Archmage Malin heeft Skuerto en mij hierheen gestuurd om ingrediënten voor hem te verzamelen. Ik wist niet hoe ik aan de spullen moest komen. Maar nu jij er bent, denk ik dat mijn probleem is opgelost.$B$BIk heb het volgende nodig: slagtanden van de Witherbark, medicijnzakjes van de Witherbark en een mes van een schaduwjager.$B$BKun je die voor me vinden? De Witherbark wonen in het zuidoosten van Arathi.",
  o = "Zoek 10 Witherbark Tusks, 4 Witherbark Medicine Pouches en een Shadow Hunter Knife voor Apprentice Kryten in Refuge Pointe.",
  p = "Heb je al geluk gehad, $N?$B$B<Kryten maakt wat aantekeningen in zijn dagboek terwijl hij leest.>$B$BAls mijn onderzoek klopt, komen de slagtanden van elke trol van de Witherbark. De medicijnzakjes komen van de medicijnmannen van de Witherbark. En de sterkste schaduwjagers van de Witherbark hebben vast het speciale mes, dat ze krijgen als ze hun overgangsrituelen hebben voltooid. Je kunt pas weten welke schaduwjagers het mes hebben als je met ze vecht.",
  c = "Ongelooflijk! Ik snap wel waarom Malin je heeft gevraagd om bij ons te komen. Echt heel goed gedaan!$B$BIn dit tempo zijn Skuerto en ik zo weer op weg naar Stormwind.$B$BIk denk dat mijn metgezel, de dwerg, terug is van zijn verkenning van Boulderfist Hall. Ga met hem praten als je klaar bent.$B$BHet leek erop dat hij een kleine schermutseling met de ogers had gehad. Maar zeg daar niets over tegen hem. Hij is heel gevoelig voor kritiek op zijn verkenningskunsten.",
  g = { {"gewicht", "weight"}, {"opgelost", "solved (oplossen)"}, {"slagtanden", "tusks (slagtand)"}, {"medicijnzakjes", "medicine pouches (medicijnzakje)"}, {"schaduwjager", "shadow hunter"}, {"dagboek", "journal"}, {"medicijnmannen", "witch doctors (medicijnman)"}, {"overgangsrituelen", "rites of passage (overgangsritueel)"}, {"voltooid", "completed (voltooien)"}, {"tempo", "pace, rate"}, {"verkenning", "scouting"}, {"schermutseling", "scuffle, skirmish"}, {"gevoelig", "sensitive"}, {"kritiek", "criticism"} },
},

[642] = { en = "The Princess Trapped", tier = 3,
  t = "De gevangen prinses",
  d = "Mijn naam is Myzrael. Ik ben een prinses van de aarde. Mijn cipiers, de reuzen, hebben me diep onder de Arathi Highlands opgesloten. Deze kristalscherven zijn de enige manier waarop ik met de wereld aan de oppervlakte kan praten.$B$BHelp me alsjeblieft. De Drywhisker Kobolds, bondgenoten van de reuzen, hebben een scherf zoals deze in hun Drywhisker Gorge, in het oosten. Om de groep scherven kracht te geven, moet je Motes of Myzrael van de kobolds verzamelen en ze op de scherven aanbrengen.$B$BIk smeek je, $N, help me!",
  o = "Verzamel 12 Motes of Myzrael en breng ze naar de Iridescent Shards in Drywhisker Gorge.",
  p = "Deze groep scherven lijkt veel op de Shards of Myzrael. Maar hetzelfde gevoel van veiligheid pulseert er niet doorheen.",
  c = "Ah! Je hebt deze scherven geactiveerd. Ik voel me nu al meer mezelf!$B$BMaar helaas ben ik nog lang niet vrij...",
  g = { {"gevangen", "trapped"}, {"cipiers", "captors, jailers (cipier)"}, {"reuzen", "giants (reus)"}, {"opgesloten", "locked up (opsluiten)"}, {"kristalscherven", "crystal shards (kristalscherf)"}, {"oppervlakte", "surface"}, {"bondgenoten", "allies (bondgenoot)"}, {"aanbrengen", "to apply"}, {"smeek", "beg (smeken)"}, {"veiligheid", "security"}, {"geactiveerd", "activated (activeren)"}, {"helaas", "alas"} },
},

[660] = { en = "Hints of a New Plague?", tier = 3,
  t = "Tekenen van een nieuwe pest?",
  d = "Goed, $N. Ik ben klaar als jij het bent.$B$BZullen we?",
  o = "Bescherm Kinelory tot ze terug is bij Quae.",
  p = "Is Kinelory veilig?",
  c = "Je hebt ons een grote dienst bewezen, $N. Dank je.$B$BIk hoop dat Kin daar beneden niet te lastig was. Ze is heel vriendelijk, maar ze kan net zo dodelijk zijn als je haar vijand bent.",
  e = "Bescherm Kinelory",
  g = { {"zullen we", "shall we"}, {"bescherm", "protect (beschermen)"}, {"veilig", "safe"}, {"een dienst bewezen", "done a service (een dienst bewijzen)"}, {"lastig", "a handful, troublesome"}, {"dodelijk", "deadly"}, {"vijand", "enemy"} },
},

[661] = { en = "Hints of a New Plague?", tier = 3,
  t = "Tekenen van een nieuwe pest?",
  d = "Ik heb Kinelory na een nacht in de herberg al veel slechter gezien dan nu. Je hebt haar duidelijk goed beschermd.$B$BMet deze spullen die ze van de boerderij heeft meegenomen, kan Phin in elk geval een idee krijgen van wat er hier in Arathi gebeurt. We blijven hier nog wat langer, om zeker te weten dat er na jouw aanval geen wraak komt. Wil jij teruggaan naar Southshore om met Phin te praten?",
  o = "Zoek Phin Odelic in Southshore.",
  c = "Dus de twee onruststokers zijn toch in orde? Haha, dat hoor ik graag. Dank je dat je me nieuws brengt over waar ze zijn en hoe het met ze gaat. Ik ben heel blij dat ze nog leven. Ze zijn allebei onvervangbaar, als vrienden en als reisgenoten.$B$BMaar... het is belangrijker dat ik je goed bedank voor je hulp. Hier. Neem dit mee, met de dank van mijn groep.$B$BMet een beetje geluk ontdekken we wat de Forsaken van plan zijn, en maken we er een einde aan.",
  g = { {"herberg", "tavern, inn"}, {"duidelijk", "obviously, clearly"}, {"meegenomen", "brought along (meenemen)"}, {"in elk geval", "at least"}, {"wraak", "retaliation, revenge"}, {"onruststokers", "troublemakers (onruststoker)"}, {"in orde", "all right"}, {"onvervangbaar", "irreplaceable"}, {"reisgenoten", "traveling companions (reisgenoot)"}, {"een einde maken aan", "to put an end to"} },
},

[682] = { en = "Stromgarde Badges", tier = 3,
  t = "Insignes van Stromgarde",
  d = "Het Syndicate in Stromgarde vecht tegen onze groep soldaten van de militie daar. De leiders van het Syndicate willen het gespuis aansporen om tegen onze beter gedisciplineerde troepen te vechten. Daarom hebben ze een premie op onze soldaten gezet. Ze geven goud voor elke Stromgarde Badge die van een gedode militieman wordt afgepakt.$B$BWe willen die insignes terug. We kunnen niet toestaan dat die moordenaars trofeeën afpakken van onze dappere gevallenen!$B$BGa het deel van Stromgarde in dat in handen is van het Syndicate, en jaag op ze om onze insignes terug te krijgen.",
  o = "Breng Stromgarde Badges naar Captain Nials in Refuge Pointe.",
  p = "Heb je al Stromgarde Badges teruggehaald, $N? Het Syndicate moet leren dat ze niet kunnen verdienen aan onze doden.",
  c = "Dank je, $N. We zullen de families van deze gevallen soldaten laten weten dat ze in de strijd zijn gesneuveld.$b$bHet zal somber nieuws zijn om te brengen. Maar het is beter dan de onzekerheid als een geliefde vermist is.",
  g = { {"insignes", "badges (insigne)"}, {"militie", "militia"}, {"gespuis", "rabble"}, {"aansporen", "to urge, spur on"}, {"gedisciplineerde", "disciplined (gedisciplineerd)"}, {"premie", "bounty"}, {"militieman", "militiaman"}, {"toestaan", "to allow"}, {"moordenaars", "cutthroats, murderers (moordenaar)"}, {"trofeeën", "trophies (trofee)"}, {"gevallenen", "the fallen (gevallene)"}, {"gesneuveld", "killed in battle (sneuvelen)"}, {"somber", "grim"}, {"onzekerheid", "uncertainty"}, {"vermist", "missing"} },
},

[651] = { en = "Stones of Binding", tier = 3,
  t = "Stenen van binding",
  d = "Er liggen vier Stones of Binding verspreid over Arathi. Deze stenen houden me vast onder de aarde.$B$BOm ze te openen, moet je de sterkste openen: de Stone of Inner Binding. En daarvoor moet je de sleutels van de andere drie verzamelen.$B$BDeze stenen worden bewaakt door wachters. Maar als je slim bent, of geluk hebt, vind je misschien manieren om ze te verbannen.",
  o = "Verzamel de Burning Key, de Cresting Key en de Thundering Key bij de Stone of West Binding, de Stone of East Binding en de Stone of Outer Binding.$B$BBreng ze naar de Stone of Inner Binding.",
  p = "Dit is de Stone of Inner Binding. Het is de sterkste van de bindstenen, en hij moet geopend worden voordat de andere open kunnen.",
  c = "<Myzrael spreekt door de steen.>$B$BHet is je gelukt! Je hebt de Stones of Binding geopend! Ik voel de boeien om me heen losser worden, en de vrijheid komt steeds dichterbij.$B$BJe bent een edele $c, $N. Mijn redder!",
  g = { {"binding", "binding"}, {"verspreid", "scattered (verspreiden)"}, {"bewaakt", "guarded (bewaken)"}, {"wachters", "guardians (wachter)"}, {"verbannen", "to banish"}, {"bindstenen", "binding stones (bindsteen)"}, {"geopend", "opened (openen)"}, {"boeien", "shackles (boei)"}, {"losser", "looser (los)"}, {"vrijheid", "freedom"}, {"edele", "noble (edel)"}, {"redder", "rescuer"} },
},

[684] = { en = "Wanted!  Marez Cowl", tier = 3,
  t = "Gezocht! Marez Cowl",
  d = "Er is een premie gezet op het hoofd van Marez Cowl, een hoge adviseur en agent van het Syndicate. Ze is voor het laatst gezien in het deel van Stromgarde dat in handen is van het Syndicate.$B$BDe premie kan worden opgehaald bij Captain Nials.$B$BWees gewaarschuwd: Marez is een bekwame en sluwe heksenmeester, bekend om haar handel met demonen. Wees uiterst voorzichtig als je op haar jaagt.",
  o = "Breng het hoofd van Marez naar Captain Nials in Refuge Pointe.",
  p = "Gegroet, $C. Heb je iets te melden?",
  c = "Heb jij Marez Cowl verslagen? Goed gedaan, $N. Echt heel goed gedaan!$b$bMarez bedreigde onze verdedigers in Stromgarde. Er wordt gezegd dat ze een gezant was tussen het Syndicate en een andere, duisterdere macht. We zijn blij dat ze haar krachten niet meer tegen ons zal gebruiken.",
  g = { {"gezocht", "wanted"}, {"premie", "bounty"}, {"adviseur", "advisor"}, {"opgehaald", "collected (ophalen)"}, {"gewaarschuwd", "warned (waarschuwen)"}, {"bekwame", "skilled (bekwaam)"}, {"sluwe", "cunning (sluw)"}, {"heksenmeester", "warlock"}, {"handel", "trafficking, dealings"}, {"uiterst", "extremely"}, {"bedreigde", "menaced, threatened (bedreigen)"}, {"verdedigers", "defenders (verdediger)"}, {"gezant", "emissary"}, {"duisterdere", "darker (duister)"} },
},

[693] = { en = "Wand over Fist", tier = 3,
  t = "Toverstaf tegen vuist",
  d = "Hé, $N. Sorry dat ik eerder zo kortaf tegen je was... en nee, dat is geen woordgrap.$B$BIk heb ontdekt waar het eerste voorwerp van Trelane terecht is gekomen: Kor'gresh heeft het in Boulderfist Hall. En zoals hij ijsstralen op zijn eigen soortgenoten afvuurde om ze in het gareel te houden, moet hij bijna doorhebben hoe hij al zijn krachten kan gebruiken.$B$BBoulderfist Hall ligt ten zuiden van hier, en dan ten oosten van Thandol Span. Zoek de oger en haal die toverstaf terug.$B$BTerwijl jij weg bent, bedenk ik wat we met Stromgarde gaan doen.",
  o = "Zoek Trelane's Wand of Invocation en breng die terug naar Skuerto in Refuge Pointe.",
  p = "Ons doel is de toverstaf, $N. Richt je daar nu op.",
  c = "Geweldig, $N. Eén voorwerp binnen, en volgens mijn lijst nog drie te gaan. De andere drie voorwerpen zijn allemaal in Stromgarde.$B$BNeem rust en kom weer op krachten. De volgende fase van mijn plan kost wat meer tijd en moeite. Kom terug naar mij als je een warme maaltijd hebt gehad en wat hebt gerust.",
  g = { {"toverstaf", "wand"}, {"vuist", "fist"}, {"kortaf", "short, curt"}, {"woordgrap", "pun"}, {"terecht is gekomen", "ended up (terechtkomen)"}, {"ijsstralen", "blasts of ice (ijsstraal)"}, {"soortgenoten", "kin, own kind (soortgenoot)"}, {"afvuurde", "fired (afvuren)"}, {"in het gareel houden", "to keep in line"}, {"doorhebben", "to figure out"}, {"bedenk", "figure out (bedenken)"}, {"op krachten komen", "to regain strength"}, {"fase", "phase"}, {"maaltijd", "meal"} },
},

[694] = { en = "Trelane's Defenses", tier = 3,
  t = "De verdediging van Trelane",
  d = "Ben je uitgerust?$B$BDit is onze volgende stap: er zijn overal ogers rond de Tower of Arathor in Stromgarde. We moeten de verdediging van de toren activeren, als je een kans wilt maken tegen ze en de voorwerpen levend wilt bereiken. Daarvoor hebben we een paar edelstenen nodig, waar de sjamanen van de Boulderfist erg op gesteld zijn geraakt. Ze hebben ze uit de toren gehaald, maar ze blijven niet lang meer in hun bezit.$B$BHaal een van die edelstenen en breng hem naar Kryten. Hij kent de spreuk om ze te betoveren, zodat ze als sleutel werken.",
  o = "Zoek een Azure Agate en breng die naar Apprentice Kryten in Refuge Pointe.",
  p = "$N, hallo weer. Heb je al een Azure Agate gevonden?",
  c = "Je verbaast me, $N. Weer goed gedaan.$B$BGeef me even om de juiste spreuk uit te spreken om de edelsteen te betoveren. Dan ben je klaar.",
  g = { {"uitgerust", "rested (uitrusten)"}, {"verdediging", "defenses, defense"}, {"activeren", "to activate"}, {"een kans maken", "to stand a chance"}, {"edelstenen", "gems (edelsteen)"}, {"sjamanen", "shamans (sjamaan)"}, {"op gesteld raken", "to take a liking to"}, {"bezit", "possession"}, {"spreuk", "spell"}, {"betoveren", "to enchant"}, {"verbaast", "amazes (verbazen)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[695] = { en = "An Apprentice's Enchantment", tier = 3,
  t = "De betovering van een leerling",
  d = "Alsjeblieft, $N. Je hoeft de edelsteen alleen tegen een van de voetstukken bij de voet van de toren te drukken om de verdediging te activeren. Gebruik hem als je klaar bent om de toren in te gaan en de overige voorwerpen van Trelane te zoeken.$B$BVeel succes. Ik wacht hier in het kamp tot je terug bent. O, en praat met Skuerto voordat je vertrekt. Hij geeft je de rest van de details die je nodig hebt.",
  o = "Praat met Skuerto.",
  c = "Goed, goed.$b$bAls er verder geen vertraging is, zullen we dan maar beginnen?",
  g = { {"betovering", "enchantment"}, {"leerling", "apprentice"}, {"voetstukken", "pedestals (voetstuk)"}, {"voet", "base, foot"}, {"drukken", "to press"}, {"overige", "remaining"}, {"kamp", "camp"}, {"vertrekt", "leave (vertrekken)"}, {"vertraging", "delay"} },
},

[696] = { en = "Attack on the Tower", tier = 3,
  t = "Aanval op de toren",
  d = "Dit is wat je zoekt: Trelane's Phylactery, Trelane's Orb en Trelane's Ember Agate.$B$BAlle drie liggen ze in kisten in de toren. Je zou de kisten zelf zonder problemen moeten kunnen openen. Je moet alleen oppassen voor de ogers.$B$BDe verdediging van de toren pakt ze niet in haar eentje aan. Je moet je wapens klaar hebben. Als die ogers merken dat je er bent en van ze steelt, zullen ze je zeker pijn doen.$B$BWees voorzichtig, en veel succes.",
  o = "Zoek Trelane's Phylactery, Trelane's Orb en Trelane's Ember Agate, en breng ze terug naar Skuerto in Refuge Pointe.",
  p = "Als je dit doet, weet ik zeker dat Malin meer dan tevreden over je zal zijn.",
  c = "Malin had niemand waardigers kunnen vragen om hierheen te komen en ons te helpen, $N. Je hebt het geweldig gedaan!$B$BHij zal blij zijn om te zien wat een enorm succes onze missie is geworden.",
  g = { {"aanval", "attack"}, {"kisten", "chests (kist)"}, {"oppassen", "to watch out"}, {"in haar eentje", "on its own"}, {"merken", "to notice, find out"}, {"steelt", "steal (stelen)"}, {"pijn doen", "to hurt"}, {"tevreden", "pleased, satisfied"}, {"waardigers", "worthier (waardig)"}, {"enorm", "overwhelming, huge"}, {"missie", "mission"} },
},

[508] = { en = "Taretha's Gift", tier = 3,
  t = "Het geschenk van Taretha",
  d = "De hanger? Natuurlijk mag je hem hebben... Neem hem! Ik wil geen herinnering aan hem... ga alsjeblieft, alsjeblieft in vrede weg...",
  o = "Breng de hanger van Taretha terug naar Krusk in Tarren Mill.",
  p = "Je bent terug, $N. Heb je succes te melden?",
  c = "Het is vreemd dat de Warchief zoveel moeite doet voor zo'n klein ding. Ik beweer niet dat ik hem begrijp, maar ik volg hem, wat hij ook beveelt. Je hebt het goed gedaan, $N. De Warchief zal ongetwijfeld blij zijn om te horen dat het je gelukt is.",
  g = { {"geschenk", "gift"}, {"hanger", "pendant"}, {"herinnering", "memory"}, {"in vrede", "in peace"}, {"melden", "to report"}, {"moeite doet", "goes to trouble (moeite doen)"}, {"beweer", "claim (beweren)"}, {"beveelt", "commands (bevelen)"}, {"ongetwijfeld", "no doubt"} },
},

})

